def compute(vars):
    reconstruction_costs = vars["v1"]
    transaction_costs = vars["v2"]
    deferred_tax_benefits = vars["v3"]

    value = reconstruction_costs + transaction_costs - deferred_tax_benefits

    return {
        "value": value,
        "trace": {
            "reconstruction_costs": reconstruction_costs,
            "transaction_costs": transaction_costs,
            "deferred_tax_benefits_offset": deferred_tax_benefits,
            "output_meta": {
                "currency": "USD",
                "scale": "million",
                "unit": None
            }
        }
    }
